import os
import zipfile
import tempfile
from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return Response('Missing file', status=400)
    file = request.files['file']
    if file.filename == '':
        return Response('No file selected', status=400)
    try:
        with tempfile.TemporaryDirectory() as tmpdir:
            zip_path = os.path.join(tmpdir, file.filename)
            file.save(zip_path)
            output = os.path.join(tmpdir, 'output.txt')
            with zipfile.ZipFile(zip_path, 'r') as zip_ref:
                # Prevent path traversal by ensuring names are safe
                for name in zip_ref.namelist():
                    safe_name = os.path.basename(name)
                    if not safe_name:
                        continue
                    full_path = os.path.join(tmpdir, safe_name)
                    if os.path.commonpath([full_path, tmpdir]) != tmpdir:
                        continue
                    if os.path.isdir(full_path):
                        continue
                    if not (safe_name.endswith('.txt') or safe_name.endswith('.text')):
                        continue
                    try:
                        with zip_ref.open(name) as f:
                            content = f.read().decode('utf-8', errors='ignore')
                            with open(output, 'a', encoding='utf-8') as out_f:
                                out_f.write(content + '\n')
                    except Exception:
                        continue
            with open(output, 'r', encoding='utf-8') as f:
                result = f.read()
            return Response(result, mimetype='text/plain')
    except Exception as e:
        return Response('Invalid input', status=400)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
